fun main() {
    runBlocking {
        val mutex = Mutex()
        var count = 0
        coroutineScope {
            repeat(2) {
                launch(Dispatchers.Default) {
                    repeat(100) { mutex.withLock { count++ } }
                }
            }
        }
        println(count)
    }
}

